    for (int i = 0; i < num; i++) {
        list->u.init_list.desig_kind[i] = dkind[i];
        list->u.init_list.desig_index[i] = dindex[i];
        list->u.init_list.desig_member[i] = dmember[i];
    }
    runtime.free(dkind);
    runtime.free(dindex);
    runtime.free(dmember);
    return list;
